///
/// 7. Virtualized watchdog tests use <c>Task.Delay(1)</c> in their
///    advance-yield loops to cooperatively yield to thread-pool pump
///    continuations; each delay is 1 ms (&lt; the 1 000 ms gate threshold).
/// </summary>

